-- PostgreSQL study assumptions: event_docs(id bigint, payload jsonb).
CREATE INDEX event_docs_payload_gin ON event_docs USING gin (payload);
SELECT id FROM event_docs WHERE payload @> '{"status":"paid"}'::jsonb;

-- PostgreSQL study assumptions: sales(id primary key, day date, amount numeric).
SELECT id, day, amount,
       SUM(amount) OVER (
         ORDER BY day, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS row_total,
       SUM(amount) OVER (
         ORDER BY day RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS day_peer_total
FROM sales;
